    expect(resolveGenre('chill', { chill: null } as unknown as Record<string, string>)).toBe(
      'music',
    );
    expect(resolveGenre('jazz', { jazz: undefined } as unknown as Record<string, string>)).toBe(
      'jazz',
    );
