  it('post200: locks src/genres.ts char-class tabs/nl/comma/colon/quotes', () => { const t = read("src/genres.ts"); expect((t.match(/\t/g) ?? []).length).toBe(0); expect((t.match(/\n/g) ?? []).length).toBe(47); expect((t.match(/,/g) ?? []).length).toBe(34); expect((t.match(/:/g) ?? []).length).toBe(26); expect((t.match(/"/g) ?? []).length).toBe(0); expect((t.match(/'/g) ?? []).length).toBe(68); });
