  it('post236-ultra: src/genres.ts L38', () => { expect(read("src/genres.ts").split('\n')[37]).toBe('export type ValidGenre = (typeof VALID_GENRES)[number];'); });
  it('post236-ultra: src/genres.ts L40', () => { expect(read("src/genres.ts").split('\n')[39]).toBe('export function resolveGenre('); });
  it('post236-ultra: src/genres.ts L43', () => { expect(read("src/genres.ts").split('\n')[42]).toBe('): string {'); });
  it('post236-ultra: src/genres.ts L46', () => { expect(read("src/genres.ts").split('\n')[45]).toBe('  return map[lower] ?? (VALID_GENRES.includes(lower as ValidGenre) ? lower : \'music\');'); });
  it('post236-ultra: HMAC post236 src/genres.ts', () => { expect(hmacSha256("post236", "src/genres.ts")).toBe("d6edce5e257f65abcb058d358baeadf659f7edd26eb3e0b6a541e6120cc7d18f"); });
