  it('post311-extras: rollingXor src/genres.ts', () => { const hex=sha256("src/genres.ts"); let a=0; for(let i=0;i<hex.length;i+=2) a^=parseInt(hex.slice(i,i+2),16); expect(a).toBe(96); });
